"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5889"],{7792(e,t,r){r.r(t),r.d(t,{metadata:()=>n,default:()=>h,frontMatter:()=>i,contentTitle:()=>a,toc:()=>l,assets:()=>c});var n=JSON.parse('{"id":"reference/register/howtos/registerSystemsToMultiplePartners","title":"How to register systems to multiple customers?","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/register/howtos/registerSystemsToMultiplePartners.md","sourceDirName":"reference/register/howtos","slug":"/reference/register/howtos/registerSystemsToMultiplePartners","permalink":"/personal-av-docs/docs/reference/register/howtos/registerSystemsToMultiplePartners","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/register/howtos/registerSystemsToMultiplePartners.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to register systems to multiple customers?","sidebar_label":"How to register systems to multiple cust","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/register/howtos/registerSystemsToMultiplePartners","format":"md"}}'),o=r(4848),s=r(8453);let i={title:"How to register systems to multiple customers?",sidebar_label:"How to register systems to multiple cust",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/register/howtos/registerSystemsToMultiplePartners",format:"md"},a,c={},l=[];function u(e){let t={a:"a",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/register/howtos/registerSystemsToMultiplePartners",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:"How to register systems to multiple customers?\nIf you have an \u201CALMS Reseller\u201D account, you can register and preconfigure devices to any ALMS account for which you know the ALMS account UID. There is no longer a requirement to have a formal Partnership with the account, although Sierra Wireless recommends that you work with your customers to ensure such partnerships are in place between your ALMS Reseller account and your customer\u2019s account. For more info about account administration and Partners, see the\nAdministration documentation\n.\nThe\nRegister for multiple companies\nlink on the Registration page allows you to upload a CSV containing settings for multiple devices, along with a\nTARGET_COMPANY\nfield where you can specify customer accounts to which the devices will be registered. This can help streamline your workflows and register devices to multiple accounts all in one registration activity.\nPlease note that you can only register one model of device (e.g. AirLink MP70) at a time.\nBefore you begin\nRegistration to customer accounts does not require that your customers grant you permanent rights to register and configure devices directly within their account. However, Sierra Wireless recommends that you review these capabilities with your customers and have them decide what level of access to provide your users.\nIf they choose to provide you with permanent access to establish these register and configuration rights, the customer will need to assign your ALMS Reseller account a user profile with sufficient rights. For more information, see the\nAdministration page\n. For a list of specific rights that should be included by your customer on the associated user profile please refer to the list below.\nIt is the customer\u2019s responsibility to grant you access rights; therefore some coordination between you and your customers may be required. Customers that created their ALMS account by using your specific referral URL will have automatically granted you all the required rights. Those rights will be in place by default, unless the customer took explicit actions to modify their partnership profile with you. If your access has been restricted, the warnings described in the Import Dependencies section below will appear after you begin the registration process. If the customer account was created from the Sierra Wireless web site account creation link, the partnership may need to be manually created. Please ask an Administrator from the customer\u2019s ALMS account to open a Support ticket with Sierra Wireless to create the partnership.\nPlease ensure that your partners have created a user profile that enabled the rights listed below on your profile:\nEntities > Settings > Create\n\u2014 enables you to clone templates\nEntities > Applications > Publish\n\u2014 enables you to share applications\nEntities > Systems > Create\n\u2014 enables you to create systems\nEntities > Systems > Activate\n\u2014 enables you to activate systems\nAccount network > Partners > View\nand\nAccount network > Profiles > View\n\u2014 enable you to view your rights\nTo register multiple systems to multiple customers from a file:\nFrom the Register page, click\nRegister for multiple companies\n.\nFrom\nRegister Operations to Customers\n, click\nDownload template\n. For more information on how to fill out the csv file, see\nCustomer Registration CSV file format\nbelow.\nAfter completing and saving the template, click\nSelect a CSV\nand upload your completed template.\nThe\nSpecify reference firmware\nand\nPre-configure Systems\noptions do not apply when using a .csv file to register systems to multiple customers.\nClick\nImport\n. The Import Dependencies window appears, showing you all the registration steps and the corresponding partner companies where the steps will take place. For more information, see\nImport Dependencies\nbelow.\nImport Dependencies\nThe Import Dependencies window may include some \u201Cdependency setup\u201D steps, which result from the preconfiguration steps that you specified. These steps may require templates and/or applications to be either available, published, or shared with each customer for the configuration step to work within their context.\nThis process requires that all of the system components you are using (templates, datasets, firmware, AAF applications) be initially available in your ALMS account before being published to your customer\u2019s account(s).\n*\nThe Import Dependencies dialog provides a summary of the actions that will take place in each customer account. Review the list of operations that will take place and click\nSetup dependencies and continue\nwhen correct.\n*\nYou may need to create and/or publish these components before starting.\nCreate template\n: Re-creates the template that resides in your account in each of the customer accounts.\nPublish Application\n: Makes an application that was released ready to install. For more information on publishing applications, see the\nApplication documentation\n.\nReuse template\n: The wizard identified an equivalent template in the customer\u2019s account that shares all the same settings. The customer\u2019s template will be used in place of the template you specified.\nShare Application\n: Shares a private application with specific customers. This step does not appear if the application is public.\nAfter you click\nSetup dependencies and continue\n, ALMS resolves the dependencies and proceeds with system registration.\nRegistration Operation for Customers without a Partnership\nAfter proceeding with system registration, one Register Request operation is created for each target company. If the partnership between the ALMS Reseller account and the customer (TARGET_COMPANY) exists, the registration goes through directly.\nIf there is no Partnership\n, the operation remains in the \u201Cpending\u201D state and the customer receives a notification that asks to accept the registration. After accepting, the devices are registered directly, and both the customer and Reseller are notified. If the customer rejects the Register Request, the register operation fails, and both customer and reseller are notified. Customers must accept or reject the request within 7 days, or the operation will time out.\nCustomers can select\nAuto-accept future requests\nto allow future registration requests from the Reseller to proceed without approval notifications. Selecting\nAuto-accept future requests\nalong with accepting the Register Request establishes a restricted partnership with the ALMS Reseller account, in which the Reseller is only permitted to register devices into that company.\nMissing Rights Error\nAn error message, such as the one in red text shown below, appears when the target customer has not granted you rights to create the system/template in their company.\nIf you see this warning, click\nCancel\n(the\nSetup dependencies and continue\nbutton is unavailable). From there, you can either:\nContact your customer to be granted the missing rights through the profile rights management page.\nExclude customers, templates or application steps that caused dependency errors from your registration setup.\nCustomer Registration CSV file format\nThe file format is a .csv file (comma separated text file). Both comma \u2018,\u2019 and semi-colon \u2018;\u2019 are supported as separators.\nFIELD\nUSE\nDESCRIPTION\nGATEWAY[IMEI]\nMandatory for all gateways or routers running ALEOS\nIMEI of the system (gateway or router) to be created. Can be retrieved or scanned from the gateway.\nGATEWAY[SERIAL NUMBER]\nMandatory for all devices running ALEOS or AirLink OS\nSerial Number of the system (gateway or router) to be created. The serial number begins with 2 letters and can be from 13 to 16 characters (skip the dash \u2018-\u2019 if there is one).\nLetters in the serial number must be in UPPER CASE.\nCan be retrieved or scanned from the device label.\nGATEWAY[REGISTRATION CODE]\nMandatory for all gateways or routers running AirLink OS\nRegistration Code of the system (gateway or router) to be created. Can be retrieved or scanned from the device label.\nMSCI[HOST]\nOptional. Not required for devices communicating via LWM2M.\nTo be filled in for the server-initiated option. If you are currently able to initiate communications out to the gateway either by public static IP or domain name, enter public IP address or complete domain name.\nCOMMUNICATION[PASSWORD]\nMandatory for devices communicating via MSCI. Optional for devices communicating via LWM2M.\nWhen communicating via MSCI, enter the ACEmanager password used to log in to this device directly. The password is required to allow ALMS to remotely change the ACEmanager password. It is also used to enable the ALEOS server-initiated communication option.\nWhen communicating via LWM2M, use this field to change the default ACEmanager password. The new password must be at least 8 characters long and include at least one number, letter, and special character.\nNAME\nOptional\nName to be set for the system.\nLABELS\nOptional\nOne or more label(s) to be applied to the created system. For providing several labels, use the pipe \u2018|\u2019 separator.\nMQTT[PASSWORD]\nMandatory for establishing MQTT connection with a message broker\nThe password is required for running applications that report MQTT to AirVantage (AVTA, for example). Use the default,\nSierra-123\n, if using the AirVantage MQTT broker for telemetry. If using a third-party MQTT broker, enter the MQTT password for that broker.\nM3DA[PASSWORD]\nMandatory for establishing M3DA connection\nThe password is required for ALEOS Application Framework (AAF) applications. The password must be at least 8 characters long and include at least one number, letter, and special character.\nTARGET_COMPANY\nMandatory to register system to desired company\nThe UID of the company to which the system will be registered. To view the UID for each company, see the My Account page for the company. The UID is on the Account details page."})]})}function h(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}},8453(e,t,r){r.d(t,{R:()=>i,x:()=>a});var n=r(6540);let o={},s=n.createContext(o);function i(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);